CREATE TABLE IF NOT EXISTS commission_closures (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),barber_id uuid NOT NULL REFERENCES barbers(id),period_start date NOT NULL,period_end date NOT NULL,revenue_cents integer NOT NULL,commission_percent numeric(5,2) NOT NULL,commission_cents integer NOT NULL,closed_by uuid NOT NULL REFERENCES users(id),closed_at timestamptz NOT NULL DEFAULT now(),UNIQUE(barber_id,period_start,period_end),CHECK(period_end>=period_start));
